  "steps": [
   {
    "n": 1,
    "title": "Soak overnight",
    "text": "Cover the beans with 6 cups of water in a pot, lid it, and leave it in the fridge overnight — 8 hours minimum."
   },
   {
    "n": 2,
    "title": "Parboil and skim",
    "text": "Add the baking soda, bring the beans to a boil and hold a simmer for 10 minutes, lifting off any foam that rises. Drain, rinse, and move them to a 5–6 qt slow cooker with a fresh 6 cups of water."
   },
   {
    "n": 3,
    "title": "Sweat the aromatics",
    "text": "Melt the butter in a sauté pan over medium-high and cook the onion, carrot and celery until they slump, about 5 minutes. Add the garlic for a final minute, then scrape it all into the cooker."
   },
   {
    "n": 4,
    "title": "The long part",
    "text": "Bury the ham hock and bay leaf in the beans. Cover and cook until the beans give completely — 3½–4½ hours on high, 4½–5½ on low. Fish out the hock, strip the meat off the bone, discard the fat, and chop the meat."
   },
   {
    "n": 5,
    "title": "Finish thick",
    "text": "Return the ham, season with salt and pepper, and stir in the potato flakes and parsley. Another 30 minutes covered and the soup will have body."
   }
  ],
